import pandas as pd
import os

files = ['ERP-2025-table10.xls', 'ERP-2025-table12.xls', 'CPI.xlsx']

for f in files:
    print(f"--- Inspecting {f} ---")
    try:
        if f.endswith('.xls'):
            # install xlrd if needed, usually pandas handles it if deps are there
            df = pd.read_excel(f, nrows=10) # Read first 10 rows to see headers
        else:
            df = pd.read_excel(f, nrows=10)

        print(df.to_string())
        print("\n")
    except Exception as e:
        print(f"Error reading {f}: {e}")

